package com.cleancity;
import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
@WebServlet("/api/admin/*") public class AdminServlet extends HttpServlet {private boolean admin(HttpServletRequest r){HttpSession s=r.getSession(false);return s!=null&&"ADMIN".equals(s.getAttribute("role"));}
 protected void doGet(HttpServletRequest r,HttpServletResponse res)throws IOException{if(!admin(r)){Json.error(res,403,"Admin access required");return;}try(Connection c=DB.get()){PreparedStatement s=c.prepareStatement("SELECT c.id,c.description,c.location,c.status,c.created_at,c.updated_at,u.name,u.email FROM complaints c JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC");ResultSet x=s.executeQuery();List<Map<String,Object>> a=new ArrayList<>();while(x.next())a.add(Map.of("id",x.getInt(1),"description",x.getString(2),"location",x.getString(3),"status",x.getString(4),"createdAt",x.getTimestamp(5).toString(),"updatedAt",x.getTimestamp(6).toString(),"userName",x.getString(7),"userEmail",x.getString(8)));Json.send(res,a);}catch(Exception e){e.printStackTrace();Json.error(res,500,"Database error");}}
 protected void doPut(HttpServletRequest r,HttpServletResponse res)throws IOException{if(!admin(r)){Json.error(res,403,"Admin access required");return;}String p=r.getPathInfo();try{int id=Integer.parseInt(p.substring(1));Map<String,String>b=Json.gson.fromJson(r.getReader(),Map.class);String st=b.get("status");if(!Set.of("Pending","In Progress","Completed").contains(st)){Json.error(res,400,"Invalid status");return;}try(Connection c=DB.get()){PreparedStatement s=c.prepareStatement("UPDATE complaints SET status=? WHERE id=?");s.setString(1,st);s.setInt(2,id);s.executeUpdate();Json.send(res,Map.of("ok",true));}}catch(Exception e){Json.error(res,500,"Could not update status");}}
}
